function plainCache(block: Block): Block {
	const out: Block = { ...block };
	const cache = out.cache_control as Json | undefined;
	if (cache && typeof cache === "object") out.cache_control = { type: "ephemeral" };
	return out;
}

/** 이 대상(`native`면 Anthropic)이 받을 thinking 블록만 남긴다. */
export function keepThinking(block: Block, target: string | "native"): Block | null {
	if (block.type === "redacted_thinking") return target === "native" ? block : null;
	if (block.type !== "thinking") return block;
	const signature = typeof block.signature === "string" ? block.signature : "";
	if (target === "native") return signature.startsWith(TAG) ? null : block;
	const tag = tagOf(target);
	if (!signature.startsWith(tag)) return null;
	return { ...block, signature: signature.slice(tag.length) };
}

/** 같은 역할이 이어지면 한 메시지로 합친다(블록을 지우고 나면 생길 수 있다). 빈 메시지는 뺀다. */
function mergeRuns(messages: Message[]): Message[] {
	const out: Message[] = [];
	for (const message of messages) {
		const content = blocks(message.content);
		if (content.length === 0) continue;
		const last = out.at(-1);
		if (last && last.role === message.role) last.content = [...blocks(last.content), ...content];
		else out.push({ role: message.role, content: [...content] });
	}
	return out;
}

/** Anthropic 직행 요청: 다른 업체가 만든 thinking 블록만 뺀다. 나머지는 손대지 않는다. */
export function forNative(body: Json): Json {
	const messages = body.messages as Message[] | undefined;
	if (!Array.isArray(messages)) return body;
	let touched = false;
	const next = messages.map((message) => {
		if (typeof message.content === "string") return message;
		const content = message.content.map((block) => keepThinking(block, "native")).filter((b): b is Block => b !== null);
		if (content.length !== message.content.length) touched = true;
		return { ...message, content };
	});
	return touched ? { ...body, messages: mergeRuns(next) } : body;
}

/** 다른 업체용 표준 Messages 요청. `provider`는 thinking 서명 태그, `model`은 업체 쪽 ID. */
export function forForeign(body: Json, provider: string, model: string, effort?: Effort): Json {
	const tools: Block[] = [];
	const toolNames = new Set<string>();
	const addTool = (tool: unknown) => {
		if (!tool || typeof tool !== "object") return;
		const source = tool as Json;
		// 서버 도구(web_search 등 type이 있는 것)는 그 업체에 없다.
		if (typeof source.type === "string" && source.type !== "custom") return;
		if (typeof source.name !== "string" || toolNames.has(source.name)) return;
		toolNames.add(source.name);
		const out: Block = {};
		for (const key of TOOL_KEYS) if (source[key] !== undefined) out[key] = source[key];
		out.input_schema = out.input_schema ? strictSchema(out.input_schema) : { type: "object", properties: {} };
		tools.push(out);
	};
	for (const tool of (body.tools as unknown[] | undefined) ?? []) addTool(tool);

	// 대화 중간 system 메시지: 텍스트는 앞(없으면 다음) user 메시지 끝에 붙인다.
	const messages: Message[] = [];
	let pending: Block[] = [];
	for (const message of (body.messages as Message[] | undefined) ?? []) {
		const content: Block[] = [];
		for (const raw of blocks(message.content)) {
			if (raw.type === "tool_addition") {
				addTool(raw.tool);
				continue;
			}
			const block = keepThinking(raw, provider);
			if (!block || !KNOWN_BLOCKS.has(String(block.type))) continue;
			const clean = plainCache(block);
			if (clean.type === "tool_use") delete clean.caller;
			if (clean.type === "thinking") delete clean.display;
			if (clean.type === "tool_result" && Array.isArray(clean.content)) {
				clean.content = (clean.content as Block[])
					.filter((part) => part.type === "text" || part.type === "image")
					.map(plainCache);
			}
			content.push(clean);
		}
		if (message.role === "system") {
			const text = content.filter((block) => block.type === "text");
			const previous = messages.at(-1);
			if (previous?.role === "user") previous.content = [...blocks(previous.content), ...text];
			else pending.push(...text);
			continue;
		}
		if (message.role === "user" && pending.length > 0) {
			content.push(...pending);
			pending = [];
		}
		messages.push({ role: message.role, content });
	}
	if (pending.length > 0) messages.push({ role: "user", content: pending });

	const out: Json = { model, messages: mergeRuns(messages), max_tokens: body.max_tokens ?? 32000 };
	for (const key of ["system", "stream", "temperature", "top_p", "top_k", "stop_sequences", "tool_choice"]) {
		if (body[key] !== undefined) out[key] = body[key];
	}
	if (Array.isArray(out.system)) out.system = (out.system as Block[]).map(plainCache);
	if (tools.length > 0) out.tools = tools;
	else delete out.tool_choice;
	const thinking = body.thinking as Json | undefined;
	if (thinking && typeof thinking === "object") {
		const { display: _display, ...rest } = thinking;
		out.thinking = rest;
	}
	const sentEffort = (body.output_config as Json | undefined)?.effort;
	const finalEffort = effort ?? sentEffort;
	if (typeof finalEffort === "string") out.output_config = { effort: finalEffort };
	return out;
}

export type Usage = { input: number; output: number; cacheRead: number };

/** SSE 응답 변환: thinking 서명에 태그를 달고, 보고 모델명을 요청한 Claude ID로 돌린다. 사용량을 모은다. */
export class StreamRewriter {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";
	#tagged = new Map<number, boolean>();
	#thinking = new Set<number>();
	readonly #tag: string;
	constructor(
		provider: string,
		private readonly requestedModel: string,
	) {
		this.#tag = tagOf(provider);
	}

	/** 받은 조각을 넣으면 내보낼 텍스트를 돌려준다(완성된 이벤트만). */
	push(chunk: string): string {
		this.#buffer += chunk;
		let out = "";
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			out += this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
		return out;
	}

	flush(): string {
		const rest = this.#buffer;
		this.#buffer = "";
		return rest.trim() ? this.#event(rest) : rest;
	}

	#event(raw: string): string {
		const lines = raw.split("\n");
		const dataAt = lines.findIndex((line) => line.startsWith("data:"));
		if (dataAt === -1) return `${raw}\n\n`;
		let data: Json;
		try {
			data = JSON.parse(lines[dataAt]!.slice(5).trim()) as Json;
		} catch {
			return `${raw}\n\n`;
		}
		const extra: string[] = [];
		const index = typeof data.index === "number" ? data.index : -1;
		switch (data.type) {
			case "message_start": {
				const message = data.message as Json | undefined;
				if (message) {
					message.model = this.requestedModel;
					this.#count(message.usage as Json | undefined);
				}
				break;
			}
			case "message_delta":
				this.#count(data.usage as Json | undefined);
				break;
			case "content_block_start": {
				const block = data.content_block as Block | undefined;
				if (block?.type === "thinking") {
					this.#thinking.add(index);
					if (typeof block.signature === "string" && block.signature) {
						block.signature = this.#tag + block.signature;
						this.#tagged.set(index, true);
					}
				}
				break;
			}
			case "content_block_delta": {
				const delta = data.delta as Json | undefined;
				if (delta?.type === "signature_delta" && !this.#tagged.get(index)) {
					delta.signature = this.#tag + String(delta.signature ?? "");
					this.#tagged.set(index, true);
				}
				break;
			}
			case "content_block_stop":
				if (this.#thinking.has(index) && !this.#tagged.get(index)) {
					this.#tagged.set(index, true);
					extra.push(
						`event: content_block_delta\ndata: ${JSON.stringify({
							type: "content_block_delta",
							index,
							delta: { type: "signature_delta", signature: this.#tag },
						})}\n\n`,
					);
				}
				break;
		}
		lines[dataAt] = `data: ${JSON.stringify(data)}`;
		return `${extra.join("")}${lines.join("\n")}\n\n`;
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		// message_start와 message_delta는 누적값을 준다: 큰 쪽을 남긴다.
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

/** 스트리밍이 아닌 응답 본문 변환. */
export function rewriteJson(body: Json, provider: string, requestedModel: string): { body: Json; usage: Usage } {
	const tag = tagOf(provider);
	const content = Array.isArray(body.content)
		? (body.content as Block[]).map((block) =>
				block.type === "thinking" ? { ...block, signature: tag + String(block.signature ?? "") } : block,
			)
		: body.content;
	const usage = (body.usage as Json | undefined) ?? {};
	const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
	return {
		body: { ...body, model: requestedModel, content },
		usage: { input: num("input_tokens"), output: num("output_tokens"), cacheRead: num("cache_read_input_tokens") },
	};
}

/** Anthropic 직행 응답의 사용량만 읽는다(바이트는 손대지 않는다). SSE면 `push`, JSON이면 `json`. */
export class UsageTap {
	usage: Usage = { input: 0, output: 0, cacheRead: 0 };
	#buffer = "";

	push(chunk: string) {
		this.#buffer += chunk;
		let cut = this.#buffer.indexOf("\n\n");
		while (cut !== -1) {
			this.#event(this.#buffer.slice(0, cut));
			this.#buffer = this.#buffer.slice(cut + 2);
			cut = this.#buffer.indexOf("\n\n");
		}
	}

	flush() {
		if (this.#buffer.trim()) this.#event(this.#buffer);
		this.#buffer = "";
	}

	json(body: unknown) {
		if (body && typeof body === "object") this.#count((body as Json).usage as Json | undefined);
	}

	#event(raw: string) {
		const line = raw.split("\n").find((entry) => entry.startsWith("data:"));
		if (!line || !line.includes('"usage"')) return;
		try {
			const data = JSON.parse(line.slice(5).trim()) as Json;
			if (data.type === "message_start") this.#count((data.message as Json | undefined)?.usage as Json | undefined);
			else if (data.type === "message_delta") this.#count(data.usage as Json | undefined);
		} catch {
			// 깨진 이벤트는 세지 않는다.
		}
	}

	#count(usage: Json | undefined) {
		if (!usage) return;
		const num = (key: string) => (typeof usage[key] === "number" ? (usage[key] as number) : 0);
		this.usage.input = Math.max(this.usage.input, num("input_tokens"));
		this.usage.output = Math.max(this.usage.output, num("output_tokens"));
		this.usage.cacheRead = Math.max(this.usage.cacheRead, num("cache_read_input_tokens"));
	}
}

import { describe, expect, test } from "bun:test";
import { aliasOf, DEFAULT_CONFIG, validate } from "./config.ts";
import { forForeign, forNative, keepThinking, rewriteJson, StreamRewriter, strictSchema, UsageTap } from "./normalize.ts";

describe("aliasOf", () => {
	test("maps Claude ids to aliases", () => {
		expect(aliasOf("claude-haiku-5-5")).toBe("haiku");
		expect(aliasOf("claude-opus-5-5[1m]")).toBe("opus");
		expect(aliasOf("claude-sonnet-5-5-20261001")).toBe("sonnet");
		expect(aliasOf("grok-4.7")).toBeNull();
		expect(aliasOf(undefined)).toBeNull();
	});
});

describe("validate", () => {
	const providers = ["opencode-go", "xai"];
	test("fills defaults", () => {
		expect(validate({}, providers)).toEqual(DEFAULT_CONFIG);
	});
	test("refuses unknown providers, duplicates, bad effort", () => {
		expect(() => validate({ routes: { haiku: { chain: [{ model: "foo/bar" }] } } }, providers)).toThrow(/not supported/);
		expect(() =>
			validate({ routes: { haiku: { chain: [{ model: "xai/grok-4.7" }, { model: "xai/grok-4.7" }] } } }, providers),
		).toThrow(/twice/);
		expect(() => validate({ routes: { haiku: { chain: [{ model: "xai/grok-4.7", effort: "ultra" }] } } }, providers)).toThrow(
			/effort/,
		);
	});
});

/** Claude Code 2.1.322가 실제로 보내는 모양(261111 캡처를 줄인 것). */
const captured = {
	model: "claude-haiku-5-5",
	max_tokens: 128000,
	stream: true,
	metadata: { user_id: '{"account_uuid":"00000000-0000-0000-0000-000000000000"}' },
	context_management: { edits: [{ type: "clear_thinking_20251015", keep: "all" }] },
	thinking: { type: "adaptive", display: "omitted" },
	output_config: { effort: "medium" },
	system: [{ type: "text", text: "You are Claude Code", cache_control: { type: "ephemeral", ttl: "1h" } }],
	tools: [
		{ name: "Read", description: "read", input_schema: { type: "object", properties: { p: { type: "string" } }, required: ["p"] } },
		{ name: "ListAgents", description: "list", input_schema: { type: "object", properties: {} } },
		{ type: "web_search_20250305", name: "web_search" },
	],
	messages: [
		{ role: "user", content: [{ type: "text", text: "hi" }] },
		{
			role: "system",
			content: [
				{ type: "text", text: "<reminder>" },
				{ type: "tool_addition", tool: { name: "Late", description: "late", input_schema: { type: "object", properties: {} } } },
			],
		},
		{
			role: "assistant",
			content: [
				{ type: "thinking", thinking: "anthropic", signature: "EqAnthropicSig" },
				{ type: "thinking", thinking: "grok", signature: "ccproxy:xai:" },
				{ type: "tool_use", id: "t1", name: "Read", input: { p: "/x" }, caller: { type: "direct" }, cache_control: { type: "ephemeral", ttl: "1h" } },
			],
		},
		{ role: "user", content: [{ type: "tool_result", tool_use_id: "t1", content: [{ type: "text", text: "ok" }, { type: "tool_reference", tool_name: "X" }] }] },
		{ role: "system", content: [{ type: "text", text: "<late reminder>" }] },
	],
};

describe("forForeign", () => {
	const out = forForeign(structuredClone(captured), "xai", "grok-4.7") as any;

	test("drops account metadata and Anthropic-only fields", () => {
		expect(out.metadata).toBeUndefined();
		expect(out.context_management).toBeUndefined();
		expect(out.thinking).toEqual({ type: "adaptive" });
		expect(out.model).toBe("grok-4.7");
		expect(out.output_config).toEqual({ effort: "medium" });
	});

	test("folds system messages into user turns and keeps roles alternating", () => {
		expect(out.messages.map((m: any) => m.role)).toEqual(["user", "assistant", "user"]);
		expect(out.messages[0].content.map((b: any) => b.text)).toEqual(["hi", "<reminder>"]);
		expect(out.messages[2].content.at(-1).text).toBe("<late reminder>");
	});

	test("moves tool_addition into tools, drops server tools, fills required", () => {
		expect(out.tools.map((t: any) => t.name)).toEqual(["Read", "ListAgents", "Late"]);
		expect(out.tools[1].input_schema.required).toEqual([]);
	});

	test("keeps only this provider's thinking, strips caller, ttl and tool_reference", () => {
		const assistant = out.messages[1].content;
		expect(assistant.filter((b: any) => b.type === "thinking")).toEqual([{ type: "thinking", thinking: "grok", signature: "" }]);
		const toolUse = assistant.find((b: any) => b.type === "tool_use");
		expect(toolUse.caller).toBeUndefined();
		expect(toolUse.cache_control).toEqual({ type: "ephemeral" });
		expect(out.messages[2].content[0].content).toEqual([{ type: "text", text: "ok" }]);
	});

	test("a route effort overrides the one Claude Code sent", () => {
		expect((forForeign(structuredClone(captured), "xai", "grok-4.7", "low") as any).output_config).toEqual({ effort: "low" });
	});
});

describe("forNative", () => {
	test("drops other providers' thinking only", () => {
		const out = forNative(structuredClone(captured)) as any;
		const thinking = out.messages[2].content.filter((b: any) => b.type === "thinking");
		expect(thinking.map((b: any) => b.signature)).toEqual(["EqAnthropicSig"]);
		expect(out.metadata).toBeDefined();
	});
	test("returns the same object when nothing changes", () => {
		const body = { model: "claude-opus-5-5", messages: [{ role: "user", content: "hi" }] };
		expect(forNative(body)).toBe(body);
	});
	test("keepThinking", () => {
		expect(keepThinking({ type: "redacted_thinking", data: "x" }, "xai")).toBeNull();
		expect(keepThinking({ type: "thinking", signature: "ccproxy:opencode-go:abc" }, "opencode-go")).toEqual({
			type: "thinking",
			signature: "abc",
		});
	});
});

describe("StreamRewriter", () => {
	const sse = (data: object) => `event: x\ndata: ${JSON.stringify(data)}\n\n`;
	test("tags thinking signatures, restores the model, counts usage across split chunks", () => {
		const rewriter = new StreamRewriter("opencode-go", "claude-haiku-5-5");
		const input =
			sse({ type: "message_start", message: { model: "deepseek-v4.1-flash", usage: { input_tokens: 10, output_tokens: 1 } } }) +
			sse({ type: "content_block_start", index: 0, content_block: { type: "thinking", thinking: "", signature: "" } }) +
			sse({ type: "content_block_stop", index: 0 }) +
			sse({ type: "content_block_start", index: 1, content_block: { type: "thinking", thinking: "" } }) +
			sse({ type: "content_block_delta", index: 1, delta: { type: "signature_delta", signature: "s1" } }) +
			sse({ type: "content_block_stop", index: 1 }) +
			sse({ type: "message_delta", usage: { output_tokens: 42 } });
		const out = rewriter.push(input.slice(0, 50)) + rewriter.push(input.slice(50)) + rewriter.flush();
		const events = out
			.split("\n\n")
			.filter(Boolean)
			.map((raw) => JSON.parse(raw.split("\n").find((l) => l.startsWith("data:"))!.slice(5)));
		expect(events[0].message.model).toBe("claude-haiku-5-5");
		expect(events.filter((e) => e.delta?.type === "signature_delta").map((e) => e.delta.signature)).toEqual([
			"ccproxy:opencode-go:",
			"ccproxy:opencode-go:s1",
		]);
		expect(rewriter.usage).toEqual({ input: 10, output: 42, cacheRead: 0 });
	});
	test("rewriteJson tags non-streamed thinking", () => {
		const { body, usage } = rewriteJson(
			{ model: "grok-4.7", content: [{ type: "thinking", thinking: "t", signature: "z" }], usage: { input_tokens: 3, output_tokens: 4 } },
			"xai",
			"claude-sonnet-5-5",
		);
		expect(body.model).toBe("claude-sonnet-5-5");
		expect((body.content as any)[0].signature).toBe("ccproxy:xai:z");
		expect(usage).toEqual({ input: 3, output: 4, cacheRead: 0 });
	});
});

test("strictSchema drops non-portable keywords, keeps property names and values", () => {
	expect(
		strictSchema({
			$schema: "https://json-schema.org/draft/2020-12/schema",
			type: "object",
			properties: {
				pattern: { type: "string", pattern: "^[^\\0]*$" },
				mode: { const: "x" },
				map: { type: "object", propertyNames: { maxLength: 4 }, additionalProperties: { type: "string" } },
			},
			required: ["pattern"],
		}),
	).toEqual({
		type: "object",
		properties: {
			pattern: { type: "string" },
			mode: { enum: ["x"] },
			map: { type: "object", additionalProperties: { type: "string" } },
		},
		required: ["pattern"],
	});
});

test("strictSchema", () => {
	expect(strictSchema({ type: "object", properties: { a: { type: "object", properties: {}, default: null } } })).toEqual({
		type: "object",
		properties: { a: { type: "object", properties: {}, required: [] } },
		required: [],
	});
});

test("UsageTap reads native usage from SSE across chunks and from JSON", () => {
	const tap = new UsageTap();
	const sse =
		`event: message_start\ndata: ${JSON.stringify({ type: "message_start", message: { usage: { input_tokens: 5, cache_read_input_tokens: 900, output_tokens: 1 } } })}\n\n` +
		`event: content_block_delta\ndata: ${JSON.stringify({ type: "content_block_delta", delta: { text: "usage" } })}\n\n` +
		`event: message_delta\ndata: ${JSON.stringify({ type: "message_delta", usage: { output_tokens: 33 } })}\n\n`;
	tap.push(sse.slice(0, 40));
	tap.push(sse.slice(40));
	tap.flush();
	expect(tap.usage).toEqual({ input: 5, output: 33, cacheRead: 900 });
	const json = new UsageTap();
	json.json({ usage: { input_tokens: 2, output_tokens: 3 } });
	expect(json.usage).toEqual({ input: 2, output: 3, cacheRead: 0 });
});

