/**
 * Thinking-level (`off`) support — pure logic.
 *
 * Whether a model may be sent `effort: "off"` is read from the model catalog
 * (`store`) with pi's model overrides applied on top, never from the provider
 * name. A model's `thinkingLevelMap` maps levels to the provider's own
 * spelling; an `off` entry of `null` means the level is unsupported, any
 * other entry (e.g. `"none"`) means it is supported, and a missing `off`
 * entry means it is supported by default. Unknown models are not allowed.
 */
import type { Effort } from "./config.ts";

type Json = Record<string, any>;

function asRecord(value: unknown): Json | null {
	return value && typeof value === "object" ? (value as Json) : null;
}

/** True when `provider/model` may be sent effort `off`, per catalog + overrides. */
export function offAllowed(store: unknown, overrides: unknown, provider: string, model: string): boolean {
	const providerEntry = asRecord(asRecord(store)?.[provider]);
	const models = Array.isArray(providerEntry?.models) ? providerEntry.models : [];
	const found = models.find((entry: unknown) => asRecord(entry)?.id === model);
	const entry = asRecord(found);
	if (!entry) return false;
	const catalog = asRecord(entry.thinkingLevelMap) ?? {};
	const overrideMap =
		asRecord(asRecord(asRecord(overrides)?.providers)?.[provider])?.modelOverrides?.[model]?.thinkingLevelMap;
	const effective = { ...catalog, ...(asRecord(overrideMap) ?? {}) };
	if ("off" in effective) return effective.off !== null && effective.off !== undefined;
	return true;
}

/** Effort to actually send: `off` falls back to `low` when the model can't do `off`. */
export function sendEffort(effort: Effort | undefined, allowed: boolean): Effort | undefined {
	if (effort === undefined) return undefined;
	if (effort === "off" && !allowed) return "low";
	return effort;
}

