		expect(forNative(body)).toBe(body);
	});
	test("keepThinking", () => {
		expect(keepThinking({ type: "redacted_thinking", data: "x" }, "xai")).toBeNull();
		expect(keepThinking({ type: "thinking", signature: "ccproxy:opencode-go:abc" }, "opencode-go")).toEqual({
			type: "thinking",
