/**
 * 공통 지시(`common`)를 system 끝에 한 번만 붙인다. 이미 있으면 같은 객체를 돌려준다.
 * system이 문자열이면 `\n\n`으로 잇고, 배열이면 text 블록을 추가한다.
 */
export function withCommon(system: unknown, common?: string): unknown {
	if (!common) return system;
	if (typeof system === "string") {
		if (system === common) return system;
		return system ? `${system}\n\n${common}` : common;
	}
	if (Array.isArray(system)) {
		if (system.some((block) => block && typeof block === "object" && (block as Block).type === "text" && (block as Block).text === common)) {
			return system;
		}
		return [...system, { type: "text", text: common }];
	}
	if (system === undefined || system === null) return [{ type: "text", text: common }];
	return system;
}

